// PILOTS MAPPING
const pilotNameIdx = pilots.headers.indexOf("NAME") !== -1 ? pilots.headers.indexOf("NAME") : pilots.headers.indexOf("PILOT_NAME");
const pilotWeightIdx = pilots.headers.indexOf("WEIGHT_KGS");
